CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), name VARCHAR(100) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, phone VARCHAR(30), password_hash TEXT NOT NULL, profile_photo TEXT, rating DECIMAL(3,2) DEFAULT 5.0, trip_count INTEGER DEFAULT 0, id_verified BOOLEAN DEFAULT FALSE, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS trips (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), driver_id UUID REFERENCES users(id) ON DELETE CASCADE, origin_lat DECIMAL(10,8) NOT NULL, origin_lng DECIMAL(11,8) NOT NULL, dest_lat DECIMAL(10,8) NOT NULL, dest_lng DECIMAL(11,8) NOT NULL, origin_name VARCHAR(200), dest_name VARCHAR(200), route_polyline JSONB, route_geom GEOGRAPHY(LINESTRING,4326), seats_available INTEGER NOT NULL DEFAULT 3 CHECK (seats_available >= 0), price_per_seat DECIMAL(8,2) DEFAULT 0, departure_time TIMESTAMPTZ, status VARCHAR(30) DEFAULT 'broadcasting', vehicle_make VARCHAR(50), vehicle_model VARCHAR(50), vehicle_year INTEGER, vehicle_plate VARCHAR(20), preferences JSONB DEFAULT '{}', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS trips_route_geom_idx ON trips USING GIST(route_geom);
CREATE INDEX IF NOT EXISTS trips_status_departure_idx ON trips(status, departure_time);
CREATE TABLE IF NOT EXISTS passenger_requests (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), user_id UUID REFERENCES users(id) ON DELETE CASCADE, pickup_lat DECIMAL(10,8) NOT NULL, pickup_lng DECIMAL(11,8) NOT NULL, pickup_name VARCHAR(200), dest_lat DECIMAL(10,8) NOT NULL, dest_lng DECIMAL(11,8) NOT NULL, dest_name VARCHAR(200), flex_radius_km INTEGER DEFAULT 8, luggage VARCHAR(20) DEFAULT 'none', preferences JSONB DEFAULT '{}', status VARCHAR(30) DEFAULT 'waiting', created_at TIMESTAMPTZ DEFAULT NOW(), expires_at TIMESTAMPTZ DEFAULT NOW() + INTERVAL '2 hours');
CREATE INDEX IF NOT EXISTS passenger_pickup_geom_idx ON passenger_requests USING GIST (ST_SetSRID(ST_MakePoint(pickup_lng,pickup_lat),4326));
CREATE INDEX IF NOT EXISTS passenger_status_expires_idx ON passenger_requests(status, expires_at);
CREATE TABLE IF NOT EXISTS bookings (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), trip_id UUID REFERENCES trips(id) ON DELETE CASCADE, passenger_id UUID REFERENCES users(id) ON DELETE CASCADE, status VARCHAR(30) DEFAULT 'pending', match_code VARCHAR(4), price_paid DECIMAL(8,2), stripe_payment_intent TEXT, rated_driver BOOLEAN DEFAULT FALSE, rated_passenger BOOLEAN DEFAULT FALSE, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE UNIQUE INDEX IF NOT EXISTS bookings_trip_passenger_unique ON bookings(trip_id, passenger_id);
CREATE TABLE IF NOT EXISTS ratings (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), booking_id UUID REFERENCES bookings(id) ON DELETE CASCADE, rater_id UUID REFERENCES users(id) ON DELETE CASCADE, rated_id UUID REFERENCES users(id) ON DELETE CASCADE, score INTEGER CHECK (score BETWEEN 1 AND 5), comment TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE OR REPLACE FUNCTION update_user_rating() RETURNS TRIGGER AS $$ BEGIN UPDATE users SET rating=(SELECT ROUND(AVG(score)::numeric,2) FROM ratings WHERE rated_id=NEW.rated_id), trip_count=trip_count+1 WHERE id=NEW.rated_id; RETURN NEW; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS after_rating_insert ON ratings;
CREATE TRIGGER after_rating_insert AFTER INSERT ON ratings FOR EACH ROW EXECUTE FUNCTION update_user_rating();
